// B — filtragem configurável. Um único item entra, um único item sai.
const envelope=$input.first().json||{};
const jobs=Array.isArray(envelope.jobs)?envelope.jobs:[];
const pref=envelope.profile||{};
const norm=value=>String(value??'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim();
const asList=value=>Array.isArray(value)?value.map(norm).filter(Boolean):[];
const locations=asList(pref.locations);
const modes=asList(pref.workModes);
const roles=asList(pref.roleKeywords);
const techs=asList(pref.technologies);
const allowedLevels=asList(pref.jobLevels);
const allowUnknownLocation=pref.allowUnknownLocation!==false;
const includeRemote=pref.includeRemote!==false;
const maxExperienceYears=Number.isFinite(Number(pref.maxExperienceYears))?Number(pref.maxExperienceYears):null;
const reasons={location:0,mode:0,role:0,technologies:0,experience:0,level:0};
function includesTerm(haystack,term){
 return norm(haystack).includes(term);
}
function check(job){
 const title=norm(job.cargo||job.title);
 const location=norm(job.local||job.location);
 const combined=norm([job.cargo,job.descricao,job.requisitos,...(job.tecnologias||[])].join(' '));
 const mode=norm(job.modalidade||job.work_mode||'nao informada');
 const remote=mode.includes('remot')||(/\bhome.?office\b/.test(mode));
 if(modes.length&&!modes.some(m=>mode.includes(m)))return 'mode';
 if(!includeRemote&&remote)return 'mode';
 if(locations.length&&!remote){
   const known=location.length>0&&!/^(ver anuncio|local nao informado|nao informado)$/.test(location);
   if((known||!allowUnknownLocation)&&!locations.some(l=>includesTerm(location,l)))return 'location';
 }
 if(roles.length&&!roles.some(r=>includesTerm(title,r)))return 'role';
 if(techs.length&&!techs.some(t=>includesTerm(combined,t)))return 'technologies';
 const level=norm(job.nivel||job.job_level||'nao informada');
 if(allowedLevels.length&&!allowedLevels.some(l=>level.includes(l)))return 'level';
 const xp=norm(job.experiencia||job.experience_requirement);
 const rawYears=job.experienciaObrigatoriaAnos??job.experience_required_years;
 const years=rawYears===null||rawYears===undefined||rawYears===''?NaN:Number(rawYears);
 if(maxExperienceYears!==null &&
   ((Number.isFinite(years)&&years>maxExperienceYears) ||
    (pref.excludeMandatoryExperience===true&&xp==='obrigatoria'&&!Number.isFinite(years))))return 'experience';
 return '';
}
const selected=[];
for(const job of jobs){
 const reason=check(job);
 if(reason)reasons[reason]++;
 else selected.push(job);
}
return [{json:{...envelope,jobs:selected,filterStats:{
 received:jobs.length,accepted:selected.length,rejected:jobs.length-selected.length,
 reasons,applied:{locations,modes,roles,techs,allowedLevels,includeRemote,maxExperienceYears}
}}}];
